// One item per bill the PMS picked to check this run.
const r = $input.first().json || {};
const bills = Array.isArray(r.bills) ? r.bills : [];
return bills.map(b => {
  const x = b.xero || {};
  const j = {
    from: b.from || '', from_email: '', subject: b.subject || '', received_at: b.received_at || '',
    message_id: b.message_id, outlook_message_id: '', outlook_categories: [],
    filename: b.filename, mime_type: 'text/plain', source_type: 'xero_bill_text',
    has_document: true, want_file: !!b.want_file, xero_text: b.xero_text,
    // Later steps use xero.tenant_id and xero.invoice_id; the PMS reads xero.tenantId and xero.invoiceId.
    xero: Object.assign({}, x, { tenant_id: x.tenantId, invoice_id: x.invoiceId, tenant_name: x.tenantName })
  };
  if (!b.want_file) j.body_text = b.xero_text;
  return { json: j };
});

// Pick the invoice file (PDF preferred, else image) from the bill's attachment list.
const items = $input.all();
const out = [];
const EXT = { pdf: 'application/pdf', png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', webp: 'image/webp' };
for (let i = 0; i < items.length; i++) {
  const src = $('Bill has a file?').itemMatching(i).json;
  const r = items[i].json || {};
  const list = (Array.isArray(r.Attachments) ? r.Attachments : []).map(a => {
    const ext = String(a.FileName || '').split('.').pop().toLowerCase();
    return { name: a.FileName, mime: EXT[ext] || '', size: Number(a.ContentLength || 0) };
  }).filter(a => a.name && a.mime);
  list.sort((a, b) => (b.mime === 'application/pdf') - (a.mime === 'application/pdf') || b.size - a.size);
  const j = Object.assign({}, src);
  if (list.length) { j.found_file = true; j.attach_file = list[0].name; j.attach_mime = list[0].mime; }
  else { j.found_file = false; j.body_text = src.xero_text; j.source_type = 'xero_bill_text'; j.mime_type = 'text/plain'; }
  out.push({ json: j, pairedItem: { item: i } });
}
return out;

// Put the downloaded invoice file on the item. If the download failed, read the bill's own Xero data instead.
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const src = $('Found a file?').itemMatching(i).json;
  const bin = it.binary ? (it.binary.data || Object.values(it.binary)[0]) : null;
  const j = Object.assign({}, src);
  if (bin && !(it.json && it.json.error)) {
    j.source_type = 'attachment'; j.filename = src.attach_file; j.mime_type = src.attach_mime; delete j.body_text;
    out.push({ json: j, binary: { data: Object.assign({}, bin, { fileName: src.attach_file, mimeType: src.attach_mime }) }, pairedItem: { item: i } });
  } else {
    j.source_type = 'xero_bill_text'; j.body_text = src.xero_text; j.mime_type = 'text/plain'; j.found_file = false;
    out.push({ json: j, pairedItem: { item: i } });
  }
}
return out;

// Pull the readable text out of an unpacked .odt (content.xml) or .docx (word/document.xml).
const NL = String.fromCharCode(10);
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const src = $('Word or ODT document?').itemMatching(i);
  const bins = items[i].binary || {};
  let xml = '';
  for (const key of Object.keys(bins)) {
    const name = String(bins[key].fileName || key).toLowerCase();
    if (name.endsWith('content.xml') || name.endsWith('document.xml')) {
      const buf = await this.helpers.getBinaryDataBuffer(i, key);
      xml = buf.toString('utf8');
      break;
    }
  }
  const text = xml
    .replace(new RegExp('<(text:tab|w:tab)[^>]*>', 'g'), ' ')
    .replace(new RegExp('<(text:line-break|w:br)[^>]*>', 'g'), NL)
    .replace(new RegExp('</(text:p|text:h|w:p)>', 'g'), NL)
    .replace(new RegExp('</(table:table-cell|w:tc)>', 'g'), ' | ')
    .replace(new RegExp('<[^>]+>', 'g'), '')
    .replace(new RegExp('&lt;', 'g'), '<').replace(new RegExp('&gt;', 'g'), '>')
    .replace(new RegExp('&quot;', 'g'), '"').replace(new RegExp('&apos;', 'g'), "'")
    .replace(new RegExp('&amp;', 'g'), '&')
    .trim()
    .slice(0, 60000);
  out.push({
    json: { ...src.json, source_type: 'document_text', body_text: text, document_text_found: text.length > 0 },
    pairedItem: { item: i }
  });
}
return out;

// Build the extraction request (instructions + document) for each attachment. The OpenAI nodes read requestBody.system and the text in requestBody.messages.
const cfg = $('Config').first().json;
const SYSTEM = "You extract data from supplier invoices for a UK property management business. Return ONLY one JSON object. No markdown fences, no commentary.

Rules:
- Copy values exactly as printed. Never guess or infer a missing value; use null instead.
- Do NOT decide whether an invoice should be paid or approved.
- Do NOT work out which property a line belongs to. Copy any property reference (address, house name, flat or unit) exactly as written next to the line, or at invoice level if it is given only once.
- Dates as YYYY-MM-DD. Amounts as plain numbers (no currency symbols). Currency as a 3-letter code.
- suggested_category must be one of: Cleaning, Maintenance and repairs, Compliance and safety, Pest control, Waste removal, Furniture and setup, Utilities and broadband, Build and refurbishment, Professional fees, Software and subscriptions, Other.
- suggested_job_type must be one of: Changeover, Midstay, Deep clean, Call-out, Other, or null if unclear.
- Invoice decision (be explicit): set is_invoice to true ONLY for a supplier invoice or a supplier credit note. Set document_type to "invoice" for an invoice (including a VAT invoice or pro-forma that requests payment) and "credit_note" for a credit note (a document titled credit note, credit memo or credit, or one that reduces or refunds an earlier invoice).
- For a credit note: put the credit note number in invoice_number and its date in invoice_date, copy amounts as positive numbers exactly as printed (do not add minus signs), and put the number of the invoice it credits in credited_invoice_reference (null if not shown).
- Everything else (a logo, signature image, quote, estimate, statement of account, payment receipt or remittance, order confirmation, reminder letter, or other) is NOT an invoice: set is_invoice to false, set document_type to quote, statement, receipt or other, and fill only document_type and legibility_confidence.
- If you cannot tell whether the document is an invoice or credit note, set is_invoice to false and explain why in extraction_notes.

Schema:
{
  "is_invoice": true,
  "document_type": "invoice | credit_note | quote | statement | receipt | other",
  "credited_invoice_reference": null,
  "legibility_confidence": 0.0,
  "supplier": {
    "name": null, "address": null, "email": null, "phone": null,
    "vat_number": null, "company_number": null,
    "bank": {"account_name": null, "sort_code": null, "account_number": null, "iban": null}
  },
  "invoice_number": null,
  "invoice_date": null,
  "due_date": null,
  "quote_or_po_reference": null,
  "addressed_to": {"name": null, "address": null},
  "currency": "GBP",
  "lines": [
    {
      "description": null,
      "property_reference_as_written": null,
      "service_date": null,
      "quantity": null,
      "net": null, "vat": null, "gross": null,
      "suggested_category": null,
      "suggested_job_type": null
    }
  ],
  "totals": {"net": null, "vat": null, "gross": null},
  "payment_terms": null,
  "extraction_notes": []
}
legibility_confidence is your own 0 to 1 estimate of how clearly the whole document could be read. Put anything unclear, cut off, handwritten or ambiguous into extraction_notes.";
const hash53 = (str, seed = 0) => { let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed; for (let i = 0; i < str.length; i++) { const ch = str.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); } h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909); h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909); return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36); };
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  let b64, block;
  if (typeof it.json.body_text === 'string') {
    const doc = 'From: ' + it.json.from + '
Subject: ' + it.json.subject + '
Received: ' + it.json.received_at + '

' + it.json.body_text;
    b64 = Buffer.from(doc, 'utf8').toString('base64');
    const intro = it.json.source_type === 'xero_bill_text'
      ? 'This supplier bill is already recorded in Xero and has no file attached. Treat the details below as the invoice. The amounts are as entered in Xero:'
      : it.json.source_type === 'document_text'
      ? 'The invoice (if any) is in the attached document ' + it.json.filename + ', converted to plain text below together with the email details:'
      : 'The invoice (if any) is in the body of this email, not an attachment. Email content:';
    block = { type: 'text', text: intro + String.fromCharCode(10, 10) + doc };
  } else {
    const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    b64 = buf.toString('base64');
    block = it.json.mime_type === 'application/pdf'
      ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } }
      : { type: 'image', source: { type: 'base64', media_type: it.json.mime_type, data: b64 } };
  }
  out.push({
    json: {
      ...it.json,
      document_base64: b64,
      doc_hash: hash53(b64) + '-' + b64.length,
      requestBody: {
        model: cfg.model,
        max_tokens: 3000,
        temperature: 0,
        system: SYSTEM,
        messages: [{ role: 'user', content: [block, { type: 'text', text: 'Extract the invoice fields as specified. Return JSON only.' }] }]
      }
    },
    binary: it.binary
  });
}
return out;

// Has this exact document been read before? Same file bytes (or same bill text) = same reading, no AI call.
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const src = $('Build AI request').itemMatching(i);
  const r = items[i].json || {};
  const ex = (r.found === true && r.extraction && typeof r.extraction === 'object') ? r.extraction : null;
  out.push({ json: Object.assign({}, src.json, { cache_hit: !!ex, cached_extraction: ex }), binary: src.binary, pairedItem: { item: i } });
}
return out;

// Cache hit: hand the saved reading straight to the parser. No file, no LLM call.
const items = $input.all();
return items.map((it, i) => ({ json: { cached_extraction: it.json.cached_extraction }, pairedItem: { item: i } }));

// Parse the model reply and build the reading to send to the PMS, with the bill it belongs to.
const cfg = $('Config').first().json;
// Reads the OpenAI reply. (The older Claude reply format is still understood, for readings saved before the switch.)
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json || {};
  const src = $('Build AI request').itemMatching(i).json;
  const isOpenAI = Array.isArray(resp.output);
  let extraction = null, extraction_error = null;
  try {
    if (resp.cached_extraction) { extraction = resp.cached_extraction; } else {
    if (!isOpenAI && !Array.isArray(resp.content) && !resp.error) throw new Error('File type not supported for reading: ' + (src.mime_type || 'unknown'));
    if (resp.error) throw new Error(typeof resp.error === 'string' ? resp.error : JSON.stringify(resp.error));
    if (isOpenAI) {
      const parts = [];
      for (const o of resp.output) for (const c of (o.content || [])) parts.push(c.text);
      const first = parts.find(p => p !== undefined && p !== null);
      extraction = (first && typeof first === 'object') ? first : JSON.parse(String(parts.join('')).replace(/```json|```/g, '').trim());
    } else {
      const text = (resp.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
      extraction = JSON.parse(text.replace(/```json|```/g, '').trim());
    }
    }
  } catch (e) {
    extraction_error = String(e.message || e).slice(0, 500);
  }
  out.push({
    json: {
      xero: src.xero,
      doc_hash: src.doc_hash || '',
      from_cache: !!resp.cached_extraction,
      provider: resp.cached_extraction ? 'cache' : 'openai',
      model: resp.cached_extraction ? 'cache' : cfg.model,
      extraction,
      extraction_error,
      source: { filename: src.filename, mime_type: src.mime_type, source_type: src.source_type }
    },
    pairedItem: { item: i }
  });
}
return out;

// One item per draft bill (or property update) the PMS asked for. Nothing here in shadow mode or for held bills.
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  if (r.action !== 'write' || !Array.isArray(r.plans)) continue;
  const src = $('Build AI request').itemMatching(i).json;
  for (const p of r.plans) {
    out.push({
      json: Object.assign({}, p, {
        review_id: r.review_id,
        filename: src.filename, mime_type: src.mime_type, source_type: src.source_type,
        document_base64: p.attach ? src.document_base64 : ''
      }),
      pairedItem: { item: i }
    });
  }
}
return out;

// Read Xero's reply, then prepare the invoice file (PDF or image) to attach to a new draft bill.
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  const src = $('Drafts to write').itemMatching(i).json;
  const inv = (r.Invoices && r.Invoices[0]) || null;
  const errs = inv && inv.ValidationErrors ? inv.ValidationErrors.map(e => e.Message).join('; ') : '';
  const ok = !!(inv && inv.InvoiceID && !errs && !r.error);
  let warn = '';
  if (ok && inv.Total !== undefined && src.plan_total !== undefined && Math.abs(Number(inv.Total) - Number(src.plan_total)) > 0.02) warn = 'Xero total ' + inv.Total + ' differs from the planned ' + src.plan_total + ': check the tax setting on the bill.';
  const errMsg = errs || (r.error ? (r.error.message || JSON.stringify(r.error)) : '') || 'No bill was returned by Xero';
  const j = {
    review_id: src.review_id, plan_index: src.plan_index, tenant_id: src.tenant_id, mime_type: src.mime_type,
    ok, xero_invoice_id: ok ? inv.InvoiceID : '', xero_status: ok ? inv.Status : '', error: ok ? warn : String(errMsg).slice(0, 500),
    attachment: '', can_attach: false
  };
  const item = { json: j, pairedItem: { item: i } };
  if (ok && src.attach && src.document_base64) {
    const name = String(src.filename || 'invoice').replace(/[^\w.\- ]+/g, '_').slice(0, 120) || 'invoice';
    item.binary = { data: await this.helpers.prepareBinaryData(Buffer.from(src.document_base64, 'base64'), name, src.mime_type || 'application/octet-stream') };
    j.can_attach = true; j.attach_name = name;
  }
  out.push(item);
}
return out;

// What happened in Xero for each draft, in the shape the PMS expects.
const items = $input.all();
return items.map((it, i) => {
  let j = it.json || {};
  let attachment = '';
  if (j.review_id === undefined) {
    // Came from "Attach invoice file to bill": the draft's result is on Prepare attachment.
    const prep = $('Prepare attachment').itemMatching(i).json;
    attachment = j.error ? 'Attachment failed: ' + String(j.error.message || JSON.stringify(j.error)).slice(0, 200) : 'Attached to bill';
    j = prep;
  }
  return { json: { review_id: j.review_id, plan_index: j.plan_index, ok: j.ok === true, xero_invoice_id: j.xero_invoice_id || '', xero_status: j.xero_status || '', error: j.error || '', attachment: attachment || j.attachment || '' }, pairedItem: { item: i } };
});
